(function deskMain(Core,M,SHA,ZIP,CSV,Binary,Maintenance,courses,sourceFiles){
"use strict";
let session=M.create(),seen=null,db=null,dirty=true,busy=false,conflict=false,storageError="",saveTimer=null,queue=Promise.resolve(),message="Complete the study setup, or open the clearly labelled authored course.",selectedFile=null,emergency={drafts:{},imports:[],reason:""};
const $=id=>document.getElementById(id),esc=x=>String(x??"").replace(/[&<>"']/g,c=>({"&":"&amp;","<":"&lt;",">":"&gt;",'"':"&quot;","'":"&#39;"}[c])),now=()=>new Date().toISOString();
const views=[["study","Study scope"],["intake","CSV intake & mapping"],["selection","Selected editions"],["records","Observed records"],["crosswalks","Identity maps"],["documents","Supporting originals"],["plan","Cohort & evaluation plan"],["timeline","Diagnosis & knowledge study"],["compare","Return comparison"],["reviews","Source & maintenance review"],["recovery","Save & recover"]];
function say(t){message=t;status();}
function hasEmergency(){return Object.keys(emergency.drafts).length>0||emergency.imports.length>0;}
function status(){if($("message"))$("message").textContent=message;if($("save-state"))$("save-state").textContent=busy?"Working…":hasEmergency()?"Pending input is in memory — download emergency recovery":conflict?"Another saved branch exists — resolve in Save & recover":storageError?"Memory only: "+storageError:dirty?"Unsaved changes":"Saved in this browser";if($("revision"))$("revision").textContent=session.study.id+" · session revision "+session.revision;}
function freeze(v){busy=v;document.querySelectorAll("button,input,select,textarea").forEach(e=>e.disabled=v);status();}
function transaction(mode,fn){return new Promise((resolve,reject)=>{if(!db)return reject(Error("Browser storage unavailable"));const tx=db.transaction("sessions",mode),st=tx.objectStore("sessions");let result;tx.oncomplete=()=>resolve(result);tx.onerror=()=>reject(tx.error||Error("Browser storage failed"));tx.onabort=()=>reject(tx.error||Error("Browser save aborted"));fn(st,x=>{result=x;},e=>{try{tx.abort();}catch{}reject(e);});});}
function checkedSaved(v){if(!v)return null;if(M.hash(v.session)!==v.hash)throw Error("Saved session digest mismatch");return {...v,session:M.normalize(v.session)};}
function readActive(){return transaction("readonly",(st,done,fail)=>{const q=st.get("active");q.onsuccess=()=>{try{const v=checkedSaved(q.result);done(v||null);}catch(e){fail(e);}};});}
function saveExact(snapshot,expected){return transaction("readwrite",(st,done,fail)=>{const q=st.get("active");q.onsuccess=()=>{try{const old=checkedSaved(q.result);if((old?.hash||null)!==expected){done({conflict:true,current:old||null});return;}const h=M.hash(snapshot);st.put({key:"active",hash:h,session:snapshot,updated_at:now()});done({hash:h});}catch(e){fail(e);}};});}
function persist(){dirty=true;clearTimeout(saveTimer);saveTimer=setTimeout(()=>{saveTimer=null;enqueueSave();},150);status();}
function enqueueSave(){queue=queue.then(async()=>{if(conflict)return;const snap=M.clone(session);try{const r=await saveExact(snap,seen);if(r.conflict){conflict=true;if(r.current)session=M.retain(session,r.current.session,"Other tab's saved branch");message="Your complete working copy and the competing saved copy are retained. Use Save & recover to select a branch.";dirty=true;}else{seen=r.hash;storageError="";dirty=hasEmergency()||M.hash(session)!==r.hash;}}catch(e){storageError=e.message;dirty=true;}status();});return queue;}
async function flush(){if(saveTimer){clearTimeout(saveTimer);saveTimer=null;enqueueSave();}await queue;}
function download(name,data,type="application/json"){const blob=new Blob([data],{type}),url=URL.createObjectURL(blob),a=document.createElement("a");a.href=url;a.download=name;document.body.appendChild(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),1000);}
function recoveryEnvelope(){return hasEmergency()?{schema:"maintenance.source-emergency/v1",session,pending_forms:emergency.drafts,pending_imports:emergency.imports,reason:emergency.reason}:session;}
function exportSession(){download(hasEmergency()?"maintenance-source-emergency-recovery.json":"maintenance-source-session.json",Core.json(recoveryEnvelope()));say(hasEmergency()?"Complete emergency recovery downloaded, including every pending form and import.":"Complete session downloaded, including every unfinished form and retained branch.");}
function draftValue(key,fallback){return emergency.drafts[key]??session.drafts[key]??fallback;}
function recordDraft(key,value){dirty=true;try{session=M.draft(session,key,value);delete emergency.drafts[key];persist();}catch(e){emergency.drafts[key]=M.clone(value);emergency.reason=e.message;dirty=true;message=e.message+" The full pending form remains in memory; use Save complete file.";status();}}
function retainImport(kind,name,text,error){const p={kind,name,text,error,at:now()},key="pending-import:"+SHA.sha256Utf8(kind+"\0"+name+"\0"+text).sha256;try{session=M.draft(session,key,p);persist();}catch(e){if(!emergency.imports.some(x=>x.key===key))emergency.imports.push({key,...p});emergency.reason=e.message;dirty=true;}}
function retainForm(key,reason){const prior=Object.hasOwn(emergency.drafts,key)?M.draft(session,key,emergency.drafts[key]):session;return M.retain(prior,prior,reason);}
function optionsHtml(values,selected,labels={}){const multi=Array.isArray(selected),chosen=multi?selected:[String(selected??"")],all=[...values,...chosen.filter(x=>!values.includes(x))];return [...new Set(all)].map(x=>'<option value="'+esc(x)+'"'+(chosen.includes(x)?" selected":"")+'>'+esc((Object.hasOwn(labels,x)?labels[x]:undefined)??(values.includes(x)?String(x).replaceAll("_"," "):"[Unresolved] "+x))+'</option>').join("");}
function control(path,label,value,{type="text",options=null,nullable=false,list=null,help=""}={}){
 const name=esc(path),v=value??"";let html;
 if(list){const chosen=Array.isArray(value)?value:[];html='<select multiple data-path="'+name+'" data-array="1">'+optionsHtml(list,chosen)+"</select>";}
 else if(options)html='<select data-path="'+name+'">'+optionsHtml(options,v)+"</select>";
 else if(type==="boolean")html='<select data-path="'+name+'" data-bool="1">'+optionsHtml(["true","false"],String(value))+"</select>";
 else if(type==="decimal")html='<input data-path="'+name+'" value="'+esc(v)+'" type="text" inputmode="decimal"'+(nullable?' data-null-text="1"':"")+">";
 else if(type==="textarea")html='<textarea rows="4" data-path="'+name+'">'+esc(v)+'</textarea>';
 else html='<input data-path="'+name+'" value="'+esc(v)+'" type="'+(type==="number"?"number":"text")+'"'+(type==="number"?' step="any" data-number="1"'+(nullable?' data-null="1"':""):"")+(["at","captured_at","available_at"].includes(path)?' placeholder="2026-10-15T00:00:00Z"':"")+">";
 return '<label>'+esc(label)+html+(help?'<small>'+esc(help)+"</small>":"")+"</label>";
}
function at(obj,path){return path.split(".").reduce((o,k)=>o?.[k],obj);}
function set(obj,path,value){const p=path.split(".");let x=obj;for(const k of p.slice(0,-1)){if(x[k]===undefined)x[k]={};x=x[k];}x[p.at(-1)]=value;}
function collect(form,convert=false){const key=form.dataset.key,base=draftValue(key,JSON.parse(form.dataset.base)),obj=M.clone(base);for(const e of form.querySelectorAll("[data-path]")){let v=e.multiple?Array.from(e.selectedOptions).map(o=>o.value):e.value;if(convert&&e.dataset.number){if(v===""){if(e.dataset.null)v=null;else throw Error(e.dataset.path+": enter a number");}else{v=Number(v);if(!Number.isFinite(v))throw Error(e.dataset.path+": enter a finite number");}}if(e.dataset.bool)v=v==="true";if(e.dataset.nullText&&v==="")v=null;if(e.dataset.roles)v=String(v).split(",").map(s=>s.trim()).filter(Boolean);set(obj,e.dataset.path,v);}return obj;}
function formOpen(key,base,kind="",oldId=""){return '<form data-key="'+esc(key)+'" data-kind="'+esc(kind)+'" data-old="'+esc(oldId)+'" data-base="'+esc(JSON.stringify(base))+'">';}
const label=k=>k.replaceAll("_"," ").replace(/^./,c=>c.toUpperCase()),fmt=x=>x===null||x===undefined?"Unobserved":String(x);
function table(headers,rows){return"<div class='table-wrap'><table><thead><tr>"+headers.map(x=>"<th>"+esc(x)+"</th>").join("")+"</tr></thead><tbody>"+rows.map(r=>"<tr>"+r.map(v=>"<td>"+esc(v)+"</td>").join("")+"</tr>").join("")+"</tbody></table></div>";}
function studyView(){const base=Object.fromEntries(Object.entries(session.study.config).filter(([k])=>!["selection","maintenance"].includes(k))),v=draftValue("config",base);return"<h1>Maintenance Incident Knowledge Study Desk</h1><p>Review supplied maintenance originals, actual diagnosis outputs and later confirmed causes. Keep the symptoms known at each output, exact machine configuration, approved knowledge edition and shift history together.</p>"+formOpen("config",base,"config")+"<div class='grid'>"+control("label","Study label",v.label)+control("data_class","Data class",v.data_class,{options:["operational","authored_course"]})+control("source_scope","Plant area, machine family and original extraction scope",v.source_scope,{type:"textarea"})+control("returned_scope","Returned trial, actual outputs and source scope",v.returned_scope,{type:"textarea"})+control("authority_notes","Actual source owners and maintenance/knowledge reviewers",v.authority_notes,{type:"textarea"})+"</div><button type='submit'>Save scope</button></form><h2>Working notes</h2><textarea id='study-notes' rows='5'>"+esc(draftValue("study-notes",{})?.text??session.study.notes)+"</textarea><button data-action='save-notes'>Save notes</button><h2>Authored ten-incident course</h2><p>Ten fictional eligible incidents retain seven ranked outputs, two abstentions and one failure. Eight later causes are confirmed: five rank-one and six top-three matches. Six paired work observations retain 180 existing versus 135 study person-minutes, including increased knowledge review. Same-machine overlapping stop records union to 30 minutes, plus 15 on another machine. These are authored records, not a product or plant result.</p><p>The first returned records contain three field changes and two changed-document findings. The corrected example retains every original. Diagnosis outputs and knowledge text remain supplied evidence; the desk does not generate a diagnosis or equipment procedure.</p><button data-action='course' data-course='first'>Open authored first return — five findings</button> <button data-action='course' data-course='corrected'>Open authored corrected return</button>";}
function intakeView(){const kind=session.selection.intakeKind||"machine_types",side=session.selection.intakeSide||"source",key="intake:"+kind+":"+side,v=draftValue(key,null);let h="<h1>Original CSV and field mapping</h1><div class='actions'>"+Core.KINDS.map(k=>"<button data-action='intake-kind' data-kind='"+k+"'"+(k===kind?" aria-current='true'":"")+">"+esc(label(k))+"</button>").join("")+"</div><div class='actions'>"+["source","returned"].map(x=>"<button data-action='intake-side' data-side='"+x+"'"+(x===side?" aria-current='true'":"")+">"+(x==="source"?"Original source":"Returned trial")+"</button>").join("")+"</div><p>Retain the approved CSV extraction exactly. A blank mapping means the field was not observed; an empty cell in a mapped column is an observed blank. IDs are text, preserving leading zeros and punctuation. The current study retains every previously imported edition.</p><div class='actions'><label class='file-label'>Choose "+esc(kind)+" CSV<input type='file' data-file='csv:"+kind+":"+side+"' accept='.csv,text/csv'></label><button data-action='csv-template' data-kind='"+kind+"'>Download canonical header template</button></div>";
if(!v)return h+"<p>No pending file for this table and side. You can switch sections without losing another table's pending file or mapping.</p>";let t;try{t=Core.inspectCSV(v.content);}catch(e){return h+"<p class='notice'>"+esc(e.message)+"</p>";}h+="<h2>"+esc(v.name)+"</h2><p>"+t.rows.length+" parsed rows; exact original remains retained with this pending mapping.</p>"+formOpen(key,{},"intake")+"<div class='grid'>"+control("label","Extract edition label",v.label)+control("available_at","This complete edition was available at (UTC)",v.available_at??v.at,{help:"Use the actual original availability instant. A later consolidated export cannot reconstruct earlier values. Capture time is retained separately."});
for(const field of Core.FIELDS[kind])h+=control("mapping."+field,label(field)+" ← original column",v.mapping[field],{options:["",...t.header],help:field==="id"?"Required stable source ID. Preserve exact original identifiers.":"Blank means unobserved; comparison will show it explicitly."});
h+="</div><button type='submit'>Retain original and select this extract</button> <button type='button' data-action='download-intake' data-key='"+esc(key)+"'>Download exact pending CSV</button></form><h2>Original row preview</h2><p>First 20 rows are shown; every parsed row is retained and compared.</p>"+table(["Original lines",...t.header],t.rows.slice(0,20).map(r=>[r.line_start+"–"+r.line_end,...r.values]));return h;}
function selectionView(){let h="<h1>Selected source and returned editions</h1><p>Each choice selects an exact original and mapping. Earlier extracts, mappings and comparisons remain in complete history. Choose a corrected returned export without replacing its first version.</p>";
for(const side of ["source","returned"]){h+="<h2>"+(side==="source"?"Original source":"Returned trial")+"</h2><div class='grid'>";for(const kind of Core.KINDS){const selected=session.study.config.selection[side][kind],es=session.study.extracts.filter(e=>e.kind===kind&&e.side===side);h+="<label>"+esc(label(kind))+"<select data-selection-kind='"+kind+"' data-selection-side='"+side+"'>"+optionsHtml(["",...es.map(e=>e.id)],selected,Object.fromEntries([["","No selected extract"],...es.map(e=>[e.id,e.label+" · "+session.study.originals.find(o=>o.id===e.original_id)?.name])]))+"</select></label>";}h+="</div>";}
h+="<h2>All retained extracts</h2>"+session.study.extracts.map(e=>"<div class='record'><strong>"+esc(e.label)+"</strong><small>"+esc(e.side+" · "+e.kind+" · available "+e.available_at+" · "+e.id)+"</small><button data-action='edit-extract' data-id='"+e.id+"'>Prepare mapping revision</button> <button data-action='download-original' data-id='"+e.original_id+"'>Download exact original</button></div>").join("");return h;}
function crosswalkView(){const kind=session.selection.mapKind||"incidents",key="crosswalk:"+kind,base={kind,pairs:session.study.crosswalks.filter(x=>x.kind===kind).map(x=>({source_id:x.source_id,target_id:x.target_id}))},v=draftValue(key,base),src=Core.rows(session.study,kind,"source"),dst=Core.rows(session.study,kind,"returned");let h="<h1>Explicit identity maps</h1><div class='actions'>"+Core.KINDS.map(k=>"<button data-action='map-kind' data-kind='"+k+"'"+(k===kind?" aria-current='true'":"")+">"+esc(label(k))+"</button>").join("")+"</div><p>Pair original IDs to returned IDs explicitly. Names and external-system references are separate evidence, not automatic identity matches. Machine types, physical machines, configuration editions, incidents, actual output snapshots, causes, knowledge editions and dated events have separate exact identities. Preserve the configuration and evidence that actually applied to each incident.</p><button data-action='match-ids' data-kind='"+kind+"'>Add unique exact-ID pairs; keep existing choices</button>"+formOpen(key,base,"crosswalk")+"<div class='table-wrap'><table><thead><tr><th>Original ID</th><th>Returned ID</th><th>Draft action</th></tr></thead><tbody>";
v.pairs.forEach((p,i)=>{h+="<tr><td>"+control("pairs."+i+".source_id","Original identity",p.source_id,{options:["",...src.map(r=>r.values.id).filter(Boolean)]})+"</td><td>"+control("pairs."+i+".target_id","Returned identity",p.target_id,{options:["",...dst.map(r=>r.values.id).filter(Boolean)]})+"</td><td><button type='button' data-action='remove-pair' data-index='"+i+"'>Remove draft pair</button></td></tr>";});h+="</tbody></table></div><button type='button' data-action='add-pair'>Add pair</button> <button type='submit'>Apply complete "+esc(kind)+" map</button></form><h2>Original identity context</h2>"+table(["ID","Original fields","Original row"],src.map(r=>[r.values.id,Object.entries(r.values).filter(([k])=>k!=="id").map(([k,v])=>k+": "+fmt(v)).join(" · "),r.source.name+":"+r.source.line_start+"–"+r.source.line_end]));return h;}
function documentsView(){const base={side:"source",kind:"diagnoses",record_id:"",document_id:"",notes:"",available_at:now()},v=draftValue("document-link",base),kind=Core.KINDS.includes(v.kind)?v.kind:"diagnoses",side=v.side==="returned"?"returned":"source";let h="<h1>Exact supporting originals</h1><p>Retain authorised diagnosis outputs, knowledge originals, source manuals, logs, technician notes, screenshots and complete incident inventory as exact bytes. Same filenames with different bytes remain distinct. Link to the exact typed source or returned record; names and captions do not establish identity. Links here annotate the selected supplied export, while source capture and availability dates remain in their exact retained editions.</p><label class='file-label'>Retain exact file<input type='file' data-file='document'></label>"+session.study.documents.map(d=>"<div class='record'><strong>"+esc(d.name)+"</strong><small>"+esc(d.media_type)+" · available "+esc(d.available_at)+" · "+d.bytes+" bytes · "+esc(d.id)+"</small><div class='mono'>"+esc(d.sha256)+"</div><p>"+esc(d.notes)+"</p><button data-action='download-document' data-id='"+d.id+"'>Download exact original</button> <button data-action='edit-document-availability' data-id='"+d.id+"'>Record source availability</button>"+(["image/png","image/jpeg","image/webp","image/gif"].includes(d.media_type)?" <button data-action='preview-document' data-id='"+d.id+"'>View retained photo</button>":"")+"</div>").join("");
const preview=session.study.documents.find(d=>d.id===session.selection.previewDocument);if(preview&&["image/png","image/jpeg","image/webp","image/gif"].includes(preview.media_type))h+="<figure><img style='max-width:100%;max-height:480px;object-fit:contain' src='data:"+esc(preview.media_type)+";base64,"+preview.base64+"' alt='"+esc(preview.name)+"'><figcaption>"+esc(preview.name+" · "+preview.sha256)+"</figcaption></figure>";
const dv=draftValue("document-availability",null);if(dv)h+="<h2>Source-backed document availability</h2>"+formOpen("document-availability",dv,"document-availability")+"<p class='mono'>"+esc(dv.document_id)+"</p><div class='grid'>"+control("available_at","Available in source (UTC)",dv.available_at)+control("reason","Original source or evidence supporting this availability",dv.reason,{type:"textarea"})+control("at","Recorded into this study (UTC)",dv.at)+"</div><button type='submit'>Retain availability correction</button></form>";
return h+"<h2>Link original to an exact record</h2>"+formOpen("document-link",base,"document-link")+"<div class='grid'>"+control("side","Evidence side",v.side,{options:["source","returned"]})+control("kind","Record kind",v.kind,{options:Core.KINDS})+control("record_id","Exact record ID",v.record_id,{options:["",...Core.rows(session.study,kind,side).map(x=>x.values.id).filter(Boolean)]})+control("document_id","Original document",v.document_id,{options:["",...session.study.documents.map(d=>d.id)]})+control("available_at","This exact record/document link was available at (UTC)",v.available_at,{help:"Source-backed link availability, separate from this file’s capture time."})+control("notes","Source link and extraction notes",v.notes,{type:"textarea"})+"</div><button type='submit'>Retain explicit document link</button></form>"+table(["Side","Kind","Record ID","Document ID","Notes"],session.study.document_links.map(x=>[x.side,x.kind,x.record_id,x.document_id,x.notes]))+session.study.document_links.map((x,i)=>"<p>"+esc(x.side+" / "+x.kind+" / "+x.record_id+" / "+x.document_id)+" <button data-action='unlink-document' data-index='"+i+"'>Remove this link; retain earlier edition</button></p>").join("");}
function compareView(){const a=M.assess(session);if(!a.ok)return"<h1>Comparison</h1><p class='notice'>"+esc(a.error)+"</p>";const r=a.result;let h="<h1>Supplied-return record comparison</h1><p class='notice'>"+esc(r.data_class)+" · "+esc(r.comparison_state)+" · "+esc(r.decision)+"</p><p>Original: "+esc(r.scope.source)+"</p><p>Returned: "+esc(r.scope.returned)+"</p>"+table(["Record kind","Original rows","Returned rows"],Core.KINDS.map(k=>[label(k),r.counts[k].source,r.counts[k].returned]))+"<h2>Exact differences and unresolved evidence</h2>"+table(["Finding","Kind / side","ID / field","Expected","Returned","Original row","Detail"],r.findings.map(x=>[x.code,x.kind+" / "+x.side,x.record_id+" / "+x.field,fmt(x.expected),fmt(x.actual),x.source?x.source.name+":"+x.source.line_start+"–"+x.source.line_end:"",x.detail]))+"<h2>Retained photo and document bytes</h2>"+table(["Kind","Original record","Returned record","Byte comparison","Original hashes","Returned hashes"],r.document_comparisons.map(d=>[d.kind,d.source_id,d.returned_id,d.state,d.source_sha256.join(", "),d.returned_sha256.join(", ")]))+"<p>Unobserved means neither side supplied linked document bytes. A matching reference alone does not establish matching attachment contents.</p><h2>Column availability</h2><p>Unobserved fields are distinct from source-observed blank cells. The export includes an explicit availability manifest.</p>"+table(["Kind / side","Extract","Unobserved columns"],Core.availability(session.study).tables.map(t=>[t.kind+" / "+t.side,t.extract_id||"None",Object.entries(t.fields).filter(([k,v])=>!v.observed).map(([k])=>k).join(", ")]))+"<h2>Interpretation</h2><p>"+esc(r.limits)+"</p><p>Equal counts alone do not establish transfer fidelity. A recorded acceptance leaves every difference visible. Review the exact selected record boundary and every unresolved identity before preparing the next trial.</p><p class='mono'>"+esc(r.study_sha256)+"</p><div class='actions'><button data-action='report'>Download comparison report</button><button data-action='export-zip'>Download complete working export</button></div>";return h;}
function reviewsView(){const base=M.reviewDraft(session),v=draftValue("review",base),stale=v.study_sha256!==Core.digest(session.study),r=Core.analyze(session.study);return"<h1>Named source and maintenance review</h1><p>Review applies to the complete current source, selected extracts, maps and document links. Earlier decisions remain historical after a change. Each configured role must accept this exact edition. A later decision supersedes that role's earlier decision for the same digest.</p>"+(stale?"<p class='notice'>This pending review belongs to an earlier edition. Its notes remain retained.</p><button data-action='new-review'>Start current review; retain earlier draft</button>":"")+formOpen("review",base,"review")+"<div class='grid'>"+control("role","Review role",v.role,{options:session.study.config.maintenance.required_review_roles})+control("reviewer","Reviewer",v.reviewer)+control("at","Reviewed at (UTC)",v.at)+control("decision","Decision",v.decision,{options:["accepted","revise"]})+control("notes","Review findings and next source correction",v.notes,{type:"textarea"})+"</div><button type='submit'>Record review</button></form>"+table(["Role / reviewer","Time","Decision","Edition","Notes"],session.study.reviews.map(x=>[x.role+" / "+x.reviewer,x.at,x.decision,x.study_sha256===r.study_sha256?"Current":"Earlier",x.notes]));}


function recordBase(kind,side){const selected=Core.selected(session.study,kind,side);return{kind,side,row_index:null,expected_extract_id:selected?.id||null,study_id:session.study.id,reason:"",at:now(),value:Object.fromEntries(Core.FIELDS[kind].map(k=>[k,!selected||selected.mapping[k]?"":null]))};}
function recordsView(){const kind=session.selection.recordKind||"incidents",side=session.selection.recordSide||"returned",key="record:"+kind+":"+side,base=recordBase(kind,side),v=draftValue(key,base),rs=Core.rows(session.study,kind,side);let h="<h1>Record an observation or correction</h1><p>Keep each observation grounded in an actual retained record. Source corrections create a later complete extract edition; the prior selected edition remains recoverable. Machine configuration, incident, diagnosis snapshot, confirmed cause set and reviewed knowledge edition have exact identities. A new dated event retains the earlier state. Enter actual supplied outputs and named source reviews; preserve unconfirmed observations explicitly.</p><div class='actions'>"+Core.KINDS.map(k=>"<button data-action='record-kind' data-kind='"+k+"'>"+esc(label(k))+"</button>").join("")+"</div><div class='actions'>"+["source","returned"].map(x=>"<button data-action='record-side' data-side='"+x+"'>"+esc(label(x))+"</button>").join("")+"</div><button data-action='new-record'>Start new record; retain draft</button>";
h+="<div class='table-wrap'><table><thead><tr><th>ID</th><th>Selected values</th><th>Action</th></tr></thead><tbody>"+rs.map((r,i)=>"<tr><td>"+esc(r.values.id)+"</td><td>"+esc(Object.entries(r.values).filter(([k])=>k!=="id").map(([k,v])=>k+": "+fmt(v)).join(" · "))+"</td><td><button data-action='edit-record' data-index='"+i+"'>Prepare correction</button>"+(kind==="knowledge"?" <button data-action='prepare-knowledge-review' data-index='"+i+"'>Prepare source review for this edition</button>":"")+"</td></tr>").join("")+"</tbody></table></div>";
h+=formOpen(key,base,"record")+"<h2>"+(v.row_index===null?"New observed record":"Correction to retained row")+"</h2><div class='grid'>";for(const k of Core.FIELDS[kind])h+=v.value[k]===null?"<p>"+esc(label(k))+": unobserved column. Prepare an explicit source mapping to add this field.</p>":control("value."+k,label(k),v.value[k],{type:["notes","description","content","symptom_summary","basis","outcome","scope","reason","exclusion_reason"].includes(k)?"textarea":"text",help:fieldHelp(kind,k)});
if(kind==="knowledge")h+="<button type='button' data-action='knowledge-content-hash'>Calculate exact content digest in this draft</button>";return h+control("reason","Source-backed reason for this new record or correction",v.reason,{type:"textarea"})+control("at","Recorded into this study (UTC)",v.at)+"</div><button type='submit'>Retain complete record revision</button></form>";}
function fieldHelp(kind,k){
 if(k.endsWith("_at")||k==="effective_from"||k==="effective_until")return"Real UTC ISO instant. Effective/observed and recorded times remain separate; blank is unobserved except an open-ended alias or downtime interval.";
 if(k==="included")return"Literal true or false. Retain the complete consecutive inventory and the source basis for any exclusion.";
 if(k==="status"&&["incidents","incident_events"].includes(kind))return"open, assigned, diagnosing, repairing, awaiting_parts, resolved, closed, reopened or cancelled; actual full dated state.";
 if(k==="output_status")return"ranked, abstained or failed exactly as supplied. Abstentions and failures remain in the eligible population.";
 if(k==="stage")return"Actual output stage. The plan selects the first supplied output at one predeclared stage.";
 if(k==="input_cutoff_at")return"Last instant at which evidence could be known to this actual diagnosis; later recorded symptoms cannot be substituted.";
 if(k==="state"&&kind==="observations")return"confirmed, conflicting or unverified, with actual observer and source role.";
 if(k==="used_value"||k==="used_state")return"Exact value/state used by this diagnosis snapshot; do not replace it with later corrections.";
 if(k==="rank")return"Supplied unique positive integer rank, starting at 1. Ties or partial ranks require source reconciliation.";
 if(k==="reported_score"||k==="score_unit")return"Retain actual supplied value and unit; this desk does not calculate a model probability.";
 if(k==="set_id")return"One explicit later confirmation set; use one row per confirmed cause. Replacement sets retain an explicit earlier set ID.";
 if(k==="status"&&kind==="confirmations")return"confirmed, unresolved or retracted; actual named confirmation basis and time are required.";
 if(k==="supersedes_set_id"||k==="supersedes_id")return"Exact earlier edition/set identity. Retain both originals and their actual chronological relationship.";
 if(k==="scope_kind")return"machine_type or configuration; configuration-specific content must name the incident's exact configuration.";
 if(k==="content_sha256")return"SHA-256 of the exact retained content text. Use the explicit digest helper after the actual content is entered.";
 if(k==="edition_sha256")return"Exact knowledge record plus linked original document hash set. Prepare this from the knowledge record; record only the actual source review.";
 if(k==="decision"&&kind==="knowledge_reviews")return"Actual source decision, such as approved or rejected; preparation of this form does not approve a procedure.";
 if(k==="active_person_minutes")return"Observed active staff minutes, including recurring confirmation, correction, review, duplicate entry and handover. Separate slices must be disjoint person-time.";
 if(k==="source_ref")return"Exact source record, file/page/line or external reference. Retain the original separately.";
 if(k==="knowledge_id")return"Exact immutable knowledge edition used or reviewed, not the latest edition substituted later.";
 if(k==="event_key")return"Canonical source stop/event identity. Overlapping intervals on one machine are unioned.";
 if(k==="ended_at"&&kind==="downtime")return"Blank means an ongoing interval censored at the as-of cutoff; missing interval rows do not mean zero downtime.";
 return"";
}
function planView(){const base=session.study.config.maintenance,v=draftValue("maintenance-plan",base);return"<h1>Incident population and evaluation plan</h1><p>Scope one plant area, machine family and complete consecutive incident inventory. Preserve unresolved incidents, actual abstentions and failed outputs. Predeclare the evaluation stage and cause-match rule; the first actual output at that stage is selected.</p>"+formOpen("maintenance-plan",base,"maintenance-plan")+"<div class='grid'>"+control("as_of","Known as of (UTC)",v.as_of)+control("side","Evidence side",v.side,{options:["source","returned"]})+control("population_start","Incident openings start (inclusive UTC)",v.population_start)+control("population_end","Incident openings end (exclusive UTC)",v.population_end)+control("inventory_complete","Complete consecutive inventory has been supplied",v.inventory_complete,{type:"boolean"})+control("inventory_document_id","Retained complete inventory original",v.inventory_document_id,{options:["",...session.study.documents.map(x=>x.id)]})+control("inventory_location","Inventory page/section/line locator",v.inventory_location)+control("selection_notes","Plant area, machine/configuration scope and exclusions",v.selection_notes,{type:"textarea"})+control("evaluation_stage","Predeclared actual-output stage",v.evaluation_stage)+control("top_k","Top K supplied ranks",v.top_k,{type:"number"})+control("cause_match","Multiple confirmed causes",v.cause_match,{options:["any_confirmed","all_confirmed"]})+control("baseline_method","Existing-work method label",v.baseline_method)+control("current_method","Study-work method label",v.current_method)+control("downtime_scope","Exact operational stop scope",v.downtime_scope)+control("measurement_notes","Source definitions, disjoint work slices and comparison limits",v.measurement_notes,{type:"textarea"})+"<label>Required observed effort phases, comma separated<input data-path='required_effort_phases' data-roles='1' value='"+esc(v.required_effort_phases.join(", "))+"'></label><label>Required study review roles, comma separated<input data-path='required_review_roles' data-roles='1' value='"+esc(v.required_review_roles.join(", "))+"'></label></div><p>Use actual active person-minutes for both methods with identical phase coverage. Include confirmation, knowledge review, reconciliation, correction, duplicate entry and handover where incurred. Missing phases are not zero. Downtime intervals are unioned within each machine and remain separate from staff work and cash.</p><button type='submit'>Retain population and evaluation plan</button></form>";}
function timelineView(){const r=Core.analyze(session.study).maintenance,d=x=>x?.decimal??"Undefined";let h="<h1>Diagnosis, knowledge and work observations</h1><p class='notice'>"+esc(r.as_of||"Cutoff not set")+" · "+esc(r.side)+" · stage "+esc(r.evaluation.stage)+" · top "+esc(r.evaluation.top_k)+"</p><p>"+esc(r.limits)+"</p>"+table(["Included","Ranked","Abstained","Failed","Missing output","Confirmed","Unresolved causes","Unresolved population"],[[r.summary.included_incidents,r.summary.selected_ranked,r.summary.selected_abstained,r.summary.selected_failed,r.summary.missing_selected_output,r.summary.confirmed_incidents,r.summary.unresolved_cause_incidents,r.summary.unresolved_population_records]])+"<h2>Separate denominators</h2>"+table(["Measure","Top 1","Top K","Population"],[["Conditional valid ranked/confirmed",d(r.summary.conditional_top_1_rate),d(r.summary.conditional_top_k_rate),r.summary.scored_ranked_incidents],["All confirmed eligible",d(r.summary.confirmed_cohort_top_1_coverage),d(r.summary.confirmed_cohort_top_k_coverage),r.summary.confirmed_incidents],["Observed successes / all eligible",d(r.summary.observed_whole_cohort_top_1_success),d(r.summary.observed_whole_cohort_top_k_success),r.summary.included_incidents]])+"<p>Unresolved causes remain unknown. Observed whole-cohort success is coverage, not an assertion that unknown outcomes were proven failures. Mean reciprocal match rank on the valid ranked/confirmed subset (first required hit for any-confirmed, last required hit for all-confirmed): "+esc(d(r.summary.mean_reciprocal_rank))+".</p><h2>Source availability</h2>"+table(["Table","Available","Known by cutoff","Retained rows","Exact extract"],r.availability.map(x=>[x.kind,x.available_at,x.known_at_cutoff,x.retained_rows,x.extract_id]))+"<h2>Complete incident population</h2>";
for(const x of r.incidents){h+="<section class='record'><h3>"+esc(x.id)+" · "+esc(x.machine_id)+" / "+esc(x.configuration_id)+"</h3>"+table(["Included","Current state","Selected output","Confirmed cause state","Confirmed causes","Top-K hit"],[[x.included,x.state?.status||x.state?.state,x.evaluation_run_id+" / "+x.evaluation_output,x.confirmed.state,x.confirmed.cause_ids.join(", "),x.top_k_hit===null?"Unresolved":x.top_k_hit]])+"<p>"+esc(x.exclusion_reason||"")+"</p><p>"+esc(x.issues.join(", ")||"No listed incident source issue.")+"</p>"+table(["State event","Effective","Recorded","Status","Assignee"],(x.state?.events||[]).map(q=>[q.id||"Opening",q.effective_at,q.recorded_at,q.status,q.assignee]));if(x.procedures.length)h+="<h4>Actual knowledge/activity references</h4>"+table(["Activity","Step","Edition","Review state","Exact digest","Issues"],x.procedures.map(q=>[q.activity_id,q.step_ref,q.knowledge.id+" / "+q.knowledge.version,q.knowledge.state,q.knowledge.edition_sha256,q.knowledge.issues.join(", ")]));if(x.handovers.length)h+="<h4>Shift handovers</h4>"+table(["From → to","Effective / recorded","Actual activity / knowledge","Acknowledged","Context","Issues"],x.handovers.map(q=>[q.from_person+" → "+q.to_person,q.effective_at+" / "+q.recorded_at,q.activity_id+" / "+q.knowledge_id,q.acknowledged,q.notes,q.issues.join(", ")]));h+="</section>";}
h+="<h2>Actual supplied output traces</h2>";for(const x of r.diagnoses)h+="<section class='record'><h3>"+esc(x.id)+" · "+esc(x.output_status)+" · "+(x.valid_for_ranking?"Source-valid ranked output":"Unscored or source review required")+"</h3><p>"+esc(x.produced_at+" · "+x.model_version+" · "+x.knowledge_release_ref+" · input cutoff "+x.input_cutoff_at)+"</p><p>"+esc(x.issues.join(", ")||"No listed output source issue.")+"</p>"+table(["Used observation","Symptom","Actual value/state","Source role","Observed","Recorded"],x.input_snapshot.map(q=>[q.observation_id,q.symptom_code,q.value+" / "+q.state,q.source_role,q.observed_at,q.recorded_at]))+table(["Supplied rank","Canonical cause","Original label","Supplied score/unit","Original row"],x.candidates.map(q=>[q.rank,q.cause_id,q.reported_label,q.reported_score+" "+q.score_unit,q.source.name+":"+q.source.line_start]))+"<p class='mono'>Original byte hashes: "+esc(x.original_sha256.join(", "))+"</p></section>";
h+="<h2>Whole-work active effort</h2><p>Current minus existing-process person-minutes. Negative means fewer observed active minutes. Missing or differently covered phases suppress the difference.</p>";for(const x of r.effort)h+="<section class='record'><h3>"+esc(x.incident_id)+"</h3><p>"+(x.comparable?"Observed difference: "+esc(d(x.delta_person_minutes))+" person-minutes":"Unobserved or unmatched whole-work coverage")+"</p>"+table(["Method","Active total","Observed phases","Issues"],Object.entries(x.methods).map(([k,v])=>[k,d(v.total),Object.entries(v.phases).map(([p,n])=>p+": "+d(n)).join(" · "),v.issues.join(", ")]))+"</section>";
h+="<h2>Machine-stop intervals</h2><p>"+esc(r.downtime.coverage)+"</p><p>Observed supplied-interval total: "+esc(d(r.downtime.total_union_machine_minutes))+" machine-minutes. Staff work is separate.</p>"+table(["Machine","Scope","Union minutes","Ongoing at cutoff","Source rows"],r.downtime.machines.map(q=>[q.machine_id,q.scope,d(q.union_machine_minutes),q.right_censored,q.retained_source_rows]));for(const x of r.downtime.machines)h+="<h3>"+esc(x.machine_id)+" interval union</h3>"+table(["Start","End/cutoff","Retained source IDs"],x.intervals.map(q=>[q.started_at,q.ended_at,q.source_ids.join(", ")]));h+=table(["Invalid stop row","Issues","Source"],r.downtime.issues.map(x=>[x.id,x.issues.join(", "),x.source.name+":"+x.source.line_start]));
return h+"<h2>Source and chronology review</h2>"+table(["Code","Table / ID","Original","Detail"],r.issues.map(x=>[x.code,x.kind+" / "+x.id,x.source?x.source.name+":"+x.source.line_start:"",x.detail]))+"<button data-action='report'>Download complete readable report</button>";}
function emergencyView(){return !hasEmergency()?"":"<section class='notice'><h2>Pending input retained in memory</h2><p>"+esc(emergency.reason)+"</p><button data-action='download-session'>Download complete emergency recovery</button><button data-action='clear-emergency'>Download and clear pending input</button>"+Object.entries(emergency.drafts).map(([k])=>"<p>Pending form: "+esc(k)+"</p>").join("")+emergency.imports.map(p=>"<p>"+esc(p.name)+" <button data-action='download-emergency-import' data-key='"+esc(p.key)+"'>Download exact file</button></p>").join("")+"</section>";}

function recoveryView(){return emergencyView()+"<h1>Save & recover</h1><p>Download the complete session to move between browsers or keep an independent copy. It includes the study, all unfinished forms, review history, source originals and retained browser branches.</p><div class='actions'><button data-action='download-session'>Download complete session</button><button data-action='export-zip'>Download complete export ZIP</button><button data-action='export-source'>Download application source ZIP</button><label class='file-label'>Open session or study JSON<input type='file' data-file='session' accept='.json,application/json'></label></div>"+(conflict?"<div class='notice'><h2>Choose how to continue</h2><p>The saved copy changed in another tab. Both copies are retained. Selecting your browser branch acknowledges the current saved copy in one atomic transaction; it remains available below.</p><button data-action='adopt-local'>Keep this browser branch; retain saved copy</button><button data-action='open-saved'>Open saved copy; retain this branch</button></div>":"")+"<h2>Retained full branches</h2>"+(session.backups.length?session.backups.map(b=>"<div class='record'><strong>"+esc(b.reason)+"</strong><small>"+esc(b.at)+" · "+esc(M.branchInfo(session,b).title)+" · revision "+M.branchInfo(session,b).revision+"</small><div class='actions'><button data-action='download-branch' data-id='"+b.hash+"'>Download complete branch</button><button data-action='open-branch' data-id='"+b.hash+"'>Open branch (retain current)</button></div></div>").join(""):"<p>No prior branch has been replaced.</p>")+"<h2>Retained import candidates</h2>"+Object.entries(session.drafts).filter(([k])=>k.startsWith("pending-import:")).map(([k,p])=>"<div class='record'><strong>"+esc(p.name)+"</strong><p>"+esc(p.error)+"</p><button data-action='download-pending' data-key='"+esc(k)+"'>Download original candidate</button><button data-action='retry-pending' data-key='"+esc(k)+"'>Retry against current study</button></div>").join("")+"<h2>Study edition history</h2>"+session.history.map((h,i)=>"<div class='record'><span>"+esc(h.at+" — "+h.reason)+"</span><button data-action='restore-edition' data-index='"+i+"'>Restore study edition (retain current session)</button></div>").join("");}
function render(){const view=session.view;document.querySelectorAll("nav button").forEach(b=>b.setAttribute("aria-current",b.dataset.view===view?"page":"false"));const fn={study:studyView,intake:intakeView,selection:selectionView,records:recordsView,plan:planView,timeline:timelineView,crosswalks:crosswalkView,documents:documentsView,compare:compareView,reviews:reviewsView,recovery:recoveryView}[view]||studyView;$("main").innerHTML=fn();status();if(busy)freeze(true);}
function replace(next,msg,clearDraftKeys=[]){M.validate(next);session=next;for(const key of clearDraftKeys)delete emergency.drafts[key];dirty=true;message=msg;persist();render();}
function retainBinary(kind,file,bytes,error){const base64=Binary.encode(bytes),p={kind,name:file.name,media_type:file.type||"application/octet-stream",base64,error,at:now()},key="pending-import:"+SHA.sha256Utf8(kind+"\0"+file.name+"\0"+base64).sha256;try{session=M.draft(session,key,p);persist();}catch(e){if(!emergency.imports.some(x=>x.key===key))emergency.imports.push({key,...p});emergency.reason=e.message;dirty=true;}}
async function openFile(file,kind){if(!file)return;if(kind==="session"&&hasEmergency()){say("Download and clear pending recovery before opening another session.");return;}if(busy)return;freeze(true);const before=M.hash(session);await flush();let retainedText=null,retainedBytes=null;try{
 if(file.size>(kind==="session"?64:24)*1024*1024)throw Error("File exceeds the import limit; choose a smaller authorised cohort");
 const bytes=new Uint8Array(await file.arrayBuffer());retainedBytes=bytes;if(M.hash(session)!==before)throw Error("Session changed during the file read; the original candidate is retained");
 let next,nextEmergency=null;
 if(kind==="document"){const study=Core.addDocument(session.study,{name:file.name,media_type:file.type||"application/octet-stream",bytes,at:now(),notes:"Exact original retained. Link to a source or returned record below."});next=M.checkpoint(session,study,"Retain original document "+file.name);next.view="documents";}
 else {const text=new TextDecoder("utf-8",{fatal:true,ignoreBOM:true}).decode(bytes);retainedText=text;
  if(kind==="session"){let x=JSON.parse(text.charCodeAt(0)===0xfeff?text.slice(1):text),pending=x.schema==="maintenance.source-emergency/v1"?x:null;if(pending)x=pending.session;
   if(x.schema===M.SCHEMA||x.schema===M.LEGACY){x=M.normalize(x);exportSession();next=M.takeSession(session,x,"Before imported replacement");}
   else {Core.validate(x);exportSession();next=M.use(session,x,"Before imported study replacement");}
   if(pending){if(!pending.pending_forms||typeof pending.pending_forms!=="object"||Array.isArray(pending.pending_forms)||!Array.isArray(pending.pending_imports))throw Error("Invalid emergency recovery");nextEmergency={drafts:{...pending.pending_forms},imports:[...pending.pending_imports],reason:pending.reason||"Imported pending recovery"};}
  } else if(kind.startsWith("csv:")){const [,recordKind,side]=kind.split(":");if(!Core.KINDS.includes(recordKind)||!["source","returned"].includes(side))throw Error("Choose record kind and side");const t=Core.inspectCSV(text),key="intake:"+recordKind+":"+side;
   next=retainForm(key,"Before replacing pending CSV "+key);next=M.draft(next,key,{kind:recordKind,side,name:file.name,content:text,label:file.name,at:now(),available_at:now(),mapping:Object.fromEntries(Core.FIELDS[recordKind].map(field=>[field,t.header.includes(field)?field:""]))});
   next.selection.intakeKind=recordKind;next.selection.intakeSide=side;next.view="intake";
  } else throw Error("Unknown import route");
 }
 M.validate(next);session=next;if(nextEmergency)emergency=nextEmergency;else if(kind.startsWith("csv:"))delete emergency.drafts["intake:"+kind.split(":")[1]+":"+kind.split(":")[2]];dirty=true;message="Opened "+file.name+". Prior applied state and unfinished forms remain recoverable.";persist();
 }catch(e){if(retainedText!==null)retainImport(kind,file.name,retainedText,e.message);else if(retainedBytes)retainBinary(kind,file,retainedBytes,e.message);message=e.message+" — selected study and readable import candidate retained.";}
 finally{freeze(false);render();}
}
async function adoptLocal(){freeze(true);await flush();try{const local=M.clone(session);const out=await transaction("readwrite",(st,done,fail)=>{const q=st.get("active");q.onsuccess=()=>{try{const old=checkedSaved(q.result);let next=old?M.retain(local,old.session,"Saved branch acknowledged during explicit adoption"):local;next=M.retain(next,local,"Local branch before explicit adoption");next.revision++;M.validate(next);const h=M.hash(next);st.put({key:"active",hash:h,session:next,updated_at:now()});done({next,hash:h});}catch(e){fail(e);}};});session=out.next;seen=out.hash;conflict=false;storageError="";dirty=hasEmergency();message="This branch is selected. Both complete preimages remain in recovery.";}catch(e){storageError=e.message;dirty=true;message="Adoption failed; both copies remain retained.";}finally{freeze(false);render();}}
async function action(el){if(busy)return;const act=el.dataset.action;try{if(hasEmergency()&&["new-study","course","open-branch","restore-edition","open-saved"].includes(act))throw Error("Resolve or download-and-clear pending input in Save & recover before replacing the study.");
 if(act==="download-session")exportSession();
 else if(act==="export-zip"){await flush();download("maintenance-source-complete.zip",ZIP.write(M.exports(session).concat(hasEmergency()?[{path:"emergency-recovery.json",content:Core.json(recoveryEnvelope())}]:[])),"application/zip");say("Complete study, report, editable tables, originals and branches exported.");}
 else if(act==="export-source"){download("maintenance-source-application-source.zip",ZIP.write(sourceFiles),"application/zip");say("Complete application source downloaded.");}
 else if(act==="report"){const a=M.assess(session);if(!a.ok)throw Error(a.error);download("maintenance-source-report.md",Core.report(session.study,a.result),"text/markdown");}

 else if(act==="csv-template"){if(!Core.KINDS.includes(el.dataset.kind))throw Error("Unknown record kind");download(el.dataset.kind+".csv",CSV.csv([Core.FIELDS[el.dataset.kind]]),"text/csv");}
 else if(act==="clear-emergency"){if(!confirm("Download the complete emergency file and clear its pending input? Applied study remains."))return;exportSession();emergency={drafts:{},imports:[],reason:""};persist();render();}
 else if(act==="download-emergency-import"){const p=emergency.imports.find(x=>x.key===el.dataset.key);if(!p)throw Error("Pending import missing");download(p.name,p.base64?Binary.decode(p.base64):p.text,p.media_type||"text/plain");}

 else if(act==="record-kind"||act==="record-side"){const next=M.clone(session);if(act==="record-kind")next.selection.recordKind=el.dataset.kind;else if(act==="record-side")next.selection.recordSide=el.dataset.side;next.revision++;replace(next,"Selection changed; unfinished forms retained.");}
 else if(act==="new-record"||act==="edit-record"){const kind=session.selection.recordKind||"incidents",side=session.selection.recordSide||"returned",key="record:"+kind+":"+side;let value=recordBase(kind,side);if(act==="edit-record"){const i=Number(el.dataset.index),row=Core.rows(session.study,kind,side)[i];if(!row)throw Error("Selected row missing");value.row_index=i;value.value=M.clone(row.values);}let next=retainForm(key,"Before preparing another record");next=M.draft(next,key,value);replace(next,"Record editor prepared; previous draft is recoverable.",[key]);}
 else if(act==="knowledge-content-hash"){const kind=session.selection.recordKind||"incidents",side=session.selection.recordSide||"returned",key="record:"+kind+":"+side;if(kind!=="knowledge")throw Error("Choose a knowledge record");const value=M.clone(draftValue(key,recordBase(kind,side)));value.value.content_sha256=SHA.sha256Utf8(value.value.content||"").sha256;let next=retainForm(key,"Before calculating content digest");next=M.draft(next,key,value);replace(next,"Exact text digest prepared. Retain the source-backed record revision explicitly.",[key]);}
 else if(act==="prepare-knowledge-review"){const side=session.selection.recordSide||"returned",row=Core.rows(session.study,"knowledge",side)[Number(el.dataset.index)];if(!row)throw Error("Knowledge row missing");const key="record:knowledge_reviews:"+side,value=recordBase("knowledge_reviews",side);value.value.knowledge_id=row.values.id;value.value.edition_sha256=Maintenance.knowledgeDigest(session.study,row.values,side);let next=retainForm(key,"Before preparing a source knowledge review");next=M.draft(next,key,value);next.selection.recordKind="knowledge_reviews";next.selection.recordSide=side;replace(next,"Exact edition digest prepared. Enter the actual named source review, decision and times.",[key]);}
 else if(act==="edit-document-availability"){const d=session.study.documents.find(x=>x.id===el.dataset.id);if(!d)throw Error("Document missing");let next=retainForm("document-availability","Before revising document availability");next=M.draft(next,"document-availability",{study_id:session.study.id,document_id:d.id,expected_sha256:d.sha256,expected_metadata_sha256:Core.hash(d),available_at:d.available_at,reason:"",at:now()});replace(next,"Document availability editor prepared; exact bytes and previous metadata retained.",["document-availability"]);}
 else if(act==="preview-document"){const next=M.clone(session);next.selection.previewDocument=el.dataset.id;next.revision++;replace(next,"Selected retained photo.");}
 else if(act==="new-review"){let next=M.retain(session,session,"Before explicitly restarting review");const old=draftValue("review",null);if(old)next=M.draft(next,"retained-review:"+M.hash(old),old);next=M.draft(next,"review",M.reviewDraft(session));replace(next,"Review started for the current complete comparison. Previous notes remain retained.",["review"]);}
 else if(act==="new-study"){if(!confirm("Start an empty study? Current complete session is retained and downloaded first."))return;exportSession();replace(M.use(session,Core.empty(),"Before new empty study"),"Empty maintenance incident study opened.");}
 else if(act==="course"){if(!confirm("Open the authored example? It contains fictional administrative data. Current session is retained."))return;exportSession();const k=el.dataset.course;if(!courses[k])throw Error("Select an example");replace(M.use(session,courses[k],"Before authored "+k+" study"),"Authored "+k+" study opened.");}
 else if(["intake-kind","intake-side","map-kind"].includes(act)){const next=M.clone(session);if(act==="intake-kind")next.selection.intakeKind=el.dataset.kind;else if(act==="intake-side")next.selection.intakeSide=el.dataset.side;else next.selection.mapKind=el.dataset.kind;next.revision++;replace(next,"Selection updated; pending forms retained.");}
 else if(act==="add-pair"||act==="remove-pair"){const kind=session.selection.mapKind||"incidents",key="crosswalk:"+kind,base={kind,pairs:session.study.crosswalks.filter(x=>x.kind===kind).map(({source_id,target_id})=>({source_id,target_id}))},v=M.clone(draftValue(key,base));let next=retainForm(key,"Before changing draft identity pairs");if(act==="add-pair")v.pairs.push({source_id:"",target_id:""});else v.pairs.splice(Number(el.dataset.index),1);next=M.draft(next,key,v);replace(next,"Draft identity pairs updated.",[key]);}
 else if(act==="match-ids"){const kind=el.dataset.kind,key="crosswalk:"+kind;let next=retainForm(key,"Before adding exact-ID pairs");next=M.checkpoint(next,Core.matchIds(next.study,kind),"Add unique exact-ID maps");delete next.drafts[key];replace(next,"Unique identical IDs added. Earlier applied maps and drafts remain recoverable.",[key]);}
 else if(act==="edit-extract"){const e=session.study.extracts.find(x=>x.id===el.dataset.id);if(!e)throw Error("Extract missing");const o=session.study.originals.find(x=>x.id===e.original_id),key="intake:"+e.kind+":"+e.side;let next=retainForm(key,"Before editing mapping "+e.id);next=M.draft(next,key,{kind:e.kind,side:e.side,name:o.name,content:o.content,label:e.label,at:now(),available_at:e.available_at,mapping:M.clone(e.mapping)});next.selection.intakeKind=e.kind;next.selection.intakeSide=e.side;next.view="intake";replace(next,"Mapping revision prepared; original extract remains retained.",[key]);}
 else if(act==="download-intake"){const p=draftValue(el.dataset.key,null);if(!p)throw Error("Pending CSV missing");download(p.name,p.content,"text/csv");}
 else if(act==="unlink-document"){const link=session.study.document_links[Number(el.dataset.index)];if(!link)throw Error("Link not found");if(!confirm("Remove this exact record-document link from the selected study? Its document and complete prior edition remain retained."))return;replace(M.checkpoint(session,Core.unlinkDocument(session.study,link),"Remove explicit record-document link"),"Link removed. Exact document and prior relationship remain recoverable.");}
 else if(act==="download-document"){const d=session.study.documents.find(x=>x.id===el.dataset.id);if(!d)throw Error("Document missing");download(d.name,Binary.decode(d.base64),d.media_type);}
 else if(act==="reset-draft"){let next=retainForm(el.dataset.key,"Before resetting draft "+el.dataset.key);delete next.drafts[el.dataset.key];next.revision++;replace(next,"Form reset; previous form is in recovery.",[el.dataset.key]);}
 else if(act==="download-pending"){const p=session.drafts[el.dataset.key];if(!p)throw Error("Import candidate not found");download(p.name,p.base64?Binary.decode(p.base64):p.text,p.media_type||"text/plain");}
 else if(act==="retry-pending"){const p=session.drafts[el.dataset.key];if(!p)throw Error("Import candidate not found");await openFile(new File([p.base64?Binary.decode(p.base64):p.text],p.name,{type:p.media_type||"text/plain"}),p.kind);}
 else if(act==="save-notes"){const st=M.clone(session.study);st.notes=draftValue("study-notes",{})?.text??$("study-notes").value;replace(M.checkpoint(session,st,"Save study notes"),"Notes saved.");}
 else if(act==="download-original"){const o=session.study.originals.find(x=>x.id===el.dataset.id);if(!o)throw Error("Original not found");download(o.name,o.content,"text/plain");}
 else if(act==="download-branch"){const b=session.backups.find(b=>b.hash===el.dataset.id);if(!b)throw Error("Branch not found");download("maintenance-source-branch-"+b.hash.slice(0,12)+".json",Core.json(M.branchSession(session,b)));}
 else if(act==="open-branch"){const b=session.backups.find(b=>b.hash===el.dataset.id);if(!b)throw Error("Branch not found");exportSession();replace(M.takeSession(session,M.branchSession(session,b),"Before opening retained branch"),"Retained branch opened. If another saved copy exists, acknowledge it explicitly.");}
 else if(act==="restore-edition"){const h=session.history[Number(el.dataset.index)];if(!h)throw Error("Edition not found");exportSession();replace(M.use(session,M.historyStudy(session,h),"Before restoring study edition"),"Study edition restored; complete prior session retained.");}
 else if(act==="adopt-local")await adoptLocal();
 else if(act==="open-saved"){freeze(true);await flush();const old=await readActive();if(!old)throw Error("No saved copy exists");exportSession();const next=M.takeSession(session,old.session,"Local session before opening saved branch");seen=old.hash;session=next;conflict=false;dirty=true;persist();message="Saved branch opened; local branch retained.";freeze(false);render();}
 }catch(e){freeze(false);say(e.message);}}
document.addEventListener("input",e=>{if(busy)return;if(e.target.id==="record-filter"){const q=e.target.value.toLowerCase();document.querySelectorAll("[data-filter]").forEach(x=>x.hidden=!x.dataset.filter.includes(q));return;}if(e.target.id==="study-notes"){recordDraft("study-notes",{text:e.target.value});return;}const form=e.target.closest("form[data-key]");if(form){recordDraft(form.dataset.key,collect(form));}});
document.addEventListener("change",e=>{if(e.target.dataset.file)openFile(e.target.files?.[0],e.target.dataset.file);else if(!busy&&e.target.dataset.selectionKind){try{const kind=e.target.dataset.selectionKind,side=e.target.dataset.selectionSide;replace(M.checkpoint(session,Core.choose(session.study,kind,side,e.target.value),"Select "+side+" "+kind),"Selected exact retained edition.");}catch(err){say(err.message);render();}}else if(!busy&&e.target.matches("select")){const form=e.target.closest("form[data-key]");if(form){recordDraft(form.dataset.key,collect(form));if(form.dataset.key==="document-link"&&["side","kind"].includes(e.target.dataset.path))render();}}});
document.addEventListener("submit",e=>{const form=e.target.closest("form[data-key]");if(!form)return;e.preventDefault();if(busy)return;try{const value=collect(form,true),kind=form.dataset.kind;let next;
 if(kind==="config"){const st=M.clone(session.study);st.config={...st.config,...value};next=M.checkpoint(session,st,"Save study scope");}

 else if(kind==="record"){if(value.study_id!==session.study.id||value.expected_extract_id!==(Core.selected(session.study,value.kind,value.side)?.id||null))throw Error("Selected records changed after this draft began; retain it and prepare a fresh correction");next=M.checkpoint(session,Core.editRow(session.study,value),"Record source-backed "+value.kind+" revision");}
 else if(kind==="maintenance-plan"){const st=M.clone(session.study);st.config.maintenance={...st.config.maintenance,...value};next=M.checkpoint(session,st,"Revise known-at population and evaluation plan");}
 else if(kind==="review")next=M.recordReview(session,value);
 else if(kind==="intake")next=M.checkpoint(session,Core.importExtract(session.study,value),"Retain original and mapped extract "+value.kind);
 else if(kind==="crosswalk")next=M.checkpoint(session,Core.crosswalk(session.study,value.kind,value.pairs),"Apply explicit identity map "+value.kind);
 else if(kind==="document-availability")next=M.checkpoint(session,Core.documentAvailability(session.study,value),"Retain sourced document availability");
 else if(kind==="document-link")next=M.checkpoint(session,Core.linkDocument(session.study,value),"Link retained record document");
 else throw Error("Unknown form");
 next=M.retain(next,session,"Complete form before saving "+form.dataset.key);delete next.drafts[form.dataset.key];replace(next,"Saved "+kind+". Comparison retains every unresolved field and source difference.",[form.dataset.key]);
 }catch(err){say(err.message+" — unfinished form retained.");}});
document.addEventListener("click",e=>{const el=e.target.closest("button");if(!el||busy)return;if(el.dataset.view){session.view=el.dataset.view;session.revision++;persist();render();}else if(el.dataset.action)action(el);});
window.addEventListener("beforeunload",e=>{if(dirty||busy||conflict||storageError||hasEmergency()){e.preventDefault();e.returnValue="";}});
// IndexedDB compare-and-swap on every commit is the saved-state authority.
$("nav").innerHTML=views.map(([v,label])=>'<button data-view="'+v+'">'+label+"</button>").join("");
render();freeze(true);
(async()=>{try{db=await new Promise((resolve,reject)=>{const q=indexedDB.open("maintenance-source-desk",1);q.onupgradeneeded=()=>{if(!q.result.objectStoreNames.contains("sessions"))q.result.createObjectStore("sessions",{keyPath:"key"});};q.onerror=()=>reject(q.error);q.onblocked=()=>reject(Error("Close another browser copy to upgrade storage"));q.onsuccess=()=>resolve(q.result);});const old=await readActive();if(old){session=old.session;seen=old.hash;dirty=M.hash(session)!==seen;if(dirty)persist();message="Complete saved session reopened, including unfinished forms.";}else{persist();}freeze(false);render();}catch(e){storageError=e.message;dirty=true;freeze(false);say("Browser storage unavailable. Download the complete session before leaving.");}})();
window.MaintenanceDesk={getSession:()=>M.clone(session),getRecovery:()=>M.clone(recoveryEnvelope()),exportFiles:()=>M.exports(session),flush,assessment:()=>M.assess(session)};
})(window.MaintenanceCore,window.MaintenanceSession,window.StudySHA,window.MaintenanceZIP,window.MaintenanceCSV,window.MaintenanceBinary,window.MaintenanceDomain,window.MAINTENANCE_COURSES,window.MAINTENANCE_SOURCE_FILES);
